const recordDeliveryOutcome = `-- name: RecordDeliveryOutcome :one
UPDATE agent_mailbox_message
SET delivery_status = CASE
        WHEN $1 = 'pending' AND withdrawn_at IS NOT NULL THEN 'failed'
        ELSE $1
    END,
    delivered_at = CASE WHEN $1 = 'delivered' THEN now() ELSE delivered_at END,
    host_receipt = COALESCE($2, host_receipt),
    last_error = CASE
        WHEN $1 = 'pending' AND withdrawn_at IS NOT NULL
            THEN COALESCE(last_error, 'Notification withdrawn before it was accepted')
        ELSE $3
    END,
    delivery_failure_streak = CASE
        WHEN $1 = 'unknown' OR ($1 = 'pending' AND $4::text = 'unavailable') THEN LEAST(delivery_failure_streak + 1, 3)
        WHEN $1 = 'pending' AND $4::text = 'dependency' AND withdrawn_at IS NULL THEN delivery_failure_streak
        ELSE 0
    END,
    delivery_retry_class = CASE WHEN $1 = 'pending' AND withdrawn_at IS NULL THEN $4::text ELSE '' END,
    next_attempt_at = CASE
        WHEN $1 = 'pending' AND withdrawn_at IS NOT NULL THEN next_attempt_at
        WHEN $1 = 'pending' AND $4::text = 'busy' THEN now() + interval '5 seconds'
        WHEN $1 = 'pending' AND $4::text = 'dependency' THEN now() + interval '120 seconds'
        WHEN $1 = 'pending' THEN now() + LEAST((LEAST(delivery_failure_streak + 1, 3))::bigint * (LEAST(delivery_failure_streak + 1, 3))::bigint * 15, 120) * interval '1 second'
        WHEN $1 = 'unknown' THEN now() + LEAST((LEAST(delivery_failure_streak + 1, 3))::bigint * (LEAST(delivery_failure_streak + 1, 3))::bigint * 15, 120) * interval '1 second'
        ELSE next_attempt_at
    END,
    lease_token_hash = NULL,
    lease_owner = NULL,
    lease_expires_at = NULL,
    updated_at = now()
WHERE id = $5
  AND workspace_id = $6
  AND delivery_status = 'leased'
  AND lease_token_hash = $7
  AND lease_expires_at > now()
  AND lease_owner = $8
RETURNING id, workspace_id, issue_id, comment_id, recipient_agent_id, source_session_id, sender_type, sender_id, delivery_status, processing_status, lease_token_hash, lease_owner, lease_expires_at, attempts, next_attempt_at, delivered_at, host_receipt, last_error, created_at, updated_at, source_type, source_key, kind, recipient_type, payload, target_session_id, notification_key, withdrawn_at, handled_by_task_id, leadership_root_issue_id, leadership_revision, delivery_failure_streak, delivery_retry_class
`

type RecordDeliveryOutcomeParams struct {
	Status         interface{} `json:"status"`
	HostReceipt    pgtype.Text `json:"host_receipt"`
	LastError      pgtype.Text `json:"last_error"`
	RetryClass     string      `json:"retry_class"`
	ID             pgtype.UUID `json:"id"`
	WorkspaceID    pgtype.UUID `json:"workspace_id"`
	LeaseTokenHash pgtype.Text `json:"lease_token_hash"`
	DaemonID       pgtype.Text `json:"daemon_id"`
}

// One fenced write for every outcome. The token, daemon and unexpired lease
// fence the update: a stale or foreign ack matches no row and cannot overwrite
// a later lease. The retry schedule separates a busy host (short fixed delay)
// from an unreachable host or a not-yet-confirmed outcome (bounded failure
// backoff).
//
// A withdrawn notification never returns to claimable delivery. A known
// no-effect answer (pending) to a row withdrawn while it was leased becomes
// failed and keeps the withdrawal reason; the host did not accept it, and the
// producer already withdrew it. Delivered and unknown keep their own truthful
// state: the marker cannot rewrite an accepted send, and an unconfirmed one is
// only ever looked up by its original id.
func (q *Queries) RecordDeliveryOutcome(ctx context.Context, arg RecordDeliveryOutcomeParams) (AgentMailboxMessage, error) {
	row := q.db.QueryRow(ctx, recordDeliveryOutcome,
		arg.Status,
		arg.HostReceipt,
		arg.LastError,
		arg.RetryClass,
		arg.ID,
		arg.WorkspaceID,
		arg.LeaseTokenHash,
		arg.DaemonID,
	)
	var i AgentMailboxMessage
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.IssueID,
		&i.CommentID,
		&i.RecipientAgentID,
		&i.SourceSessionID,
		&i.SenderType,
		&i.SenderID,
		&i.DeliveryStatus,
		&i.ProcessingStatus,
		&i.LeaseTokenHash,
		&i.LeaseOwner,
		&i.LeaseExpiresAt,
		&i.Attempts,
		&i.NextAttemptAt,
		&i.DeliveredAt,
		&i.HostReceipt,
		&i.LastError,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SourceType,
		&i.SourceKey,
		&i.Kind,
		&i.RecipientType,
		&i.Payload,
		&i.TargetSessionID,
		&i.NotificationKey,
		&i.WithdrawnAt,
		&i.HandledByTaskID,
		&i.LeadershipRootIssueID,
		&i.LeadershipRevision,
		&i.DeliveryFailureStreak,
		&i.DeliveryRetryClass,
	)
	return i, err
}

const tryLockDeliveryTarget = `-- name: TryLockDeliveryTarget :one
SELECT pg_try_advisory_xact_lock(hashtextextended($1::text, 0)) AS locked
`

// Transaction-scoped advisory lock that serialises claims for one physical
// session, so two daemons cannot lease different rows for the same session at
// once. Two sessions of the same agent are different keys and proceed
// independently.
func (q *Queries) TryLockDeliveryTarget(ctx context.Context, targetSessionID string) (bool, error) {
	row := q.db.QueryRow(ctx, tryLockDeliveryTarget, targetSessionID)
	var locked bool
	err := row.Scan(&locked)
	return locked, err
}

const wakeOfflineDeliveriesForHost = `-- name: WakeOfflineDeliveriesForHost :exec
UPDATE agent_mailbox_message m
SET next_attempt_at = now(), updated_at = now()
FROM external_agent_session target, external_agent_session recovered
WHERE recovered.id = $1
  AND recovered.workspace_id = $2
  AND recovered.daemon_id = $3
  AND target.workspace_id = recovered.workspace_id
  AND target.daemon_id = recovered.daemon_id
  AND target.provider = recovered.provider
  AND target.host_id = recovered.host_id
  AND m.workspace_id = recovered.workspace_id
  AND m.target_session_id = target.id
  AND m.id <> $4
  AND m.delivery_status = 'pending'
  AND m.delivery_retry_class = 'unavailable'
  AND m.next_attempt_at > now()
`

type WakeOfflineDeliveriesForHostParams struct {
	TargetSessionID pgtype.UUID `json:"target_session_id"`
	WorkspaceID     pgtype.UUID `json:"workspace_id"`
	DaemonID        string      `json:"daemon_id"`
	DeliveryID      pgtype.UUID `json:"delivery_id"`
}

// A successful or busy response proves this daemon can reach the host again.
// Only known-no-effect offline retries are accelerated; unknown outcomes stay
// on the receipt-verification schedule and dependency failures are untouched.
func (q *Queries) WakeOfflineDeliveriesForHost(ctx context.Context, arg WakeOfflineDeliveriesForHostParams) error {
	_, err := q.db.Exec(ctx, wakeOfflineDeliveriesForHost,
		arg.TargetSessionID,
		arg.WorkspaceID,
		arg.DaemonID,
		arg.DeliveryID,
	)
	return err
}

const withdrawAgentDeliveries = `-- name: WithdrawAgentDeliveries :execrows
UPDATE agent_mailbox_message
SET delivery_status = CASE WHEN delivery_status = 'pending' THEN 'failed' ELSE delivery_status END,
    withdrawn_at = COALESCE(withdrawn_at, now()),
    -- A pending row's withdrawal is certain, so the reason is the reason. A
    -- leased or unknown row keeps any diagnostic it already had (the host may
    -- have said something useful); the marker still records the withdrawal.
    last_error = CASE WHEN delivery_status = 'pending' THEN $1
                      ELSE COALESCE(NULLIF(last_error, ''), $1) END,
    updated_at = now()
WHERE recipient_agent_id = ANY($2::uuid[])
  AND target_session_id IS NOT NULL
  AND delivery_status IN ('pending','leased','unknown')
  AND withdrawn_at IS NULL
`

type WithdrawAgentDeliveriesParams struct {
	Reason   pgtype.Text   `json:"reason"`
	AgentIds []pgtype.UUID `json:"agent_ids"`
}

// Withdraws the unaccepted notifications of archived agents. It runs in the
// same transaction as the archive write, so an archive can never commit while
// a notification it should have withdrawn stays claimable. Pending rows become
// failed; leased and unknown rows keep their transport state (the host may
// already have acted) and carry withdrawn_at so a known no-effect answer can
// never return them to claimable delivery. target_session_id scopes it to the
// delivery core: legacy internal-mailbox rows have no target and are consumed
// through processing_status, so their delivery_status must stay untouched.
func (q *Queries) WithdrawAgentDeliveries(ctx context.Context, arg WithdrawAgentDeliveriesParams) (int64, error) {
	result, err := q.db.Exec(ctx, withdrawAgentDeliveries, arg.Reason, arg.AgentIds)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
